css:
/* Card Monthly Card Print — RTL A4 portrait, wkhtmltopdf-safe.
   Palette: dark slate #24364a structure + teal #0f766e accent (print-safe).
   No external fonts/CSS/JS; colors are literals (old WebKit has no CSS vars).
   Printable area fit: A4 210mm - 2x10mm margins = 190mm. The root is capped at
   190mm with a 2.5mm inner gutter, box-sizing is border-box everywhere, and
   every table is table-layout:fixed at width:100% so no cell content can
   expand a table past the printable width (old-WebKit nowrap bug). */
.card-pf {
  direction: rtl;
  text-align: right;
  font-family: "Noto Sans Arabic", "Noto Sans", "Segoe UI", Tahoma, Arial, sans-serif;
  color: #1f2937;
  font-size: 9.5px;
  line-height: 1.45;
  -webkit-print-color-adjust: exact;
  print-color-adjust: exact;
}
.card-pf, .card-pf * { -webkit-box-sizing: border-box; box-sizing: border-box; }
.card-pf table { width: 100%; max-width: 100%; table-layout: fixed; border-collapse: collapse; }
.card-pf th, .card-pf td { word-wrap: break-word; overflow-wrap: anywhere; }
.card-pf img { border: 0; }
.card-pf bdi { direction: ltr; unicode-bidi: embed; }

/* ---------- header ---------- */
.card-pf .pf-head { border-bottom: 2.5px solid #24364a; }
.card-pf .pf-head td { vertical-align: middle; padding: 0 0 7px 0; border: 0; }
.card-pf .pf-logo-cell { width: 96px; text-align: right; }
.card-pf .pf-logo { max-height: 58px; max-width: 88px; }
.card-pf .pf-brand { padding-right: 8px; }
.card-pf .pf-company { font-size: 16px; font-weight: 700; color: #24364a; }
.card-pf .pf-company-meta { margin-top: 2px; color: #5f6b7a; font-size: 8.5px; }
.card-pf .pf-company-meta span { margin-left: 12px; }
.card-pf .pf-title { text-align: left; width: 34%; }
.card-pf .pf-title-main { font-size: 14px; font-weight: 700; color: #0f766e; }
.card-pf .pf-title-en { font-size: 8px; color: #8b97a5; letter-spacing: 1px; text-transform: uppercase; }
.card-pf .pf-docno { font-size: 11px; font-weight: 600; color: #1f2937; margin-top: 2px; }
.card-pf .pf-badge { display: inline-block; margin-top: 3px; padding: 1px 9px; border-radius: 8px; font-size: 8.5px; font-weight: 700; border: 1px solid #b9c4d0; }
.card-pf .pf-badge-draft { color: #5f6b7a; background: #eef2f7 !important; }
.card-pf .pf-badge-cancelled { color: #ffffff !important; border-color: #b42318; background: #b42318 !important; }

/* ---------- period band ---------- */
.cpf-cmc .pf-period-band { margin: 7px 0 6px; padding: 4px 12px; background: #24364a !important; color: #ffffff !important; border-radius: 3px; overflow: hidden; white-space: normal; word-wrap: break-word; }
.cpf-cmc .pf-period-month { font-size: 12px; font-weight: 700; color: #ffffff !important; }
.cpf-cmc .pf-period-range { float: left; font-size: 9px; color: #c9d4e0 !important; margin-top: 2px; padding-right: 8px; }

/* ---------- meta grid ---------- */
.cpf-cmc .pf-meta { margin: 0 0 7px; }
.cpf-cmc .pf-meta th, .cpf-cmc .pf-meta td { border: 1px solid #dde4ec; padding: 3px 6px; font-size: 9px; vertical-align: middle; overflow: hidden; }
.cpf-cmc .pf-meta th { width: 11.5%; background: #eef2f7 !important; color: #24364a; font-weight: 700; white-space: normal; }
.cpf-cmc .pf-meta td { width: 21.8%; }
.cpf-cmc .pf-meta .pf-blank { background: #ffffff !important; }

/* ---------- days grid (31 rows on one page) ---------- */
.cpf-cmc .pf-days thead th { background: #24364a !important; color: #ffffff !important; border: 1px solid #24364a; padding: 2.5px 4px; font-size: 8.5px; font-weight: 700; text-align: right; line-height: 1.3; overflow: hidden; }
.cpf-cmc .pf-days thead th.c-idx, .cpf-cmc .pf-days thead th.c-date, .cpf-cmc .pf-days thead th.c-hours { text-align: center; }
.cpf-cmc .pf-days td { border: 1px solid #dde4ec; padding: 1.5px 4px; height: 12px; font-size: 8.8px; overflow: hidden; }
.cpf-cmc .pf-days .c-idx { width: 4%; text-align: center; color: #5f6b7a; }
.cpf-cmc .pf-days .c-date { width: 8.5%; text-align: center; }
.cpf-cmc .pf-days .c-day { width: 10%; }
.cpf-cmc .pf-days .c-status { width: 11.5%; }
.cpf-cmc .pf-days .c-hours { width: 9%; text-align: center; font-weight: 600; }
.cpf-cmc .pf-days .c-idle { width: 27%; }
.cpf-cmc .pf-days .c-notes { width: 30%; }
.cpf-cmc .pf-days tr { page-break-inside: avoid; }
.cpf-cmc .pf-row-alt td { background: #f7fafc !important; }
.cpf-cmc .pf-row-friday td { background: #e9eef5 !important; }
.cpf-cmc .pf-row-off td { color: #8b97a5; }
.cpf-cmc .pf-empty { text-align: center; color: #8b97a5; padding: 8px; }

/* ---------- totals ---------- */
.cpf-cmc .pf-stats { margin-top: 7px; border-collapse: separate !important; border-spacing: 5px 0; }
.cpf-cmc .pf-stat { border: 1px solid #b9c4d0; border-radius: 4px; background: #eef2f7 !important; text-align: center; padding: 5px 4px; }
.cpf-cmc .pf-stat-label { display: block; font-size: 8.5px; color: #5f6b7a; font-weight: 700; margin-bottom: 2px; }
.cpf-cmc .pf-stat-value { display: block; font-size: 14px; font-weight: 700; color: #24364a; }
.cpf-cmc .pf-stat-accent { background: #e8f4f2 !important; border-color: #0f766e; }
.cpf-cmc .pf-stat-accent .pf-stat-value { color: #0f766e; }

.cpf-cmc .pf-settle { margin-top: 6px; page-break-inside: avoid; }
.cpf-cmc .pf-settle td { border: 1px solid #b9c4d0; padding: 4px 8px; width: 25%; vertical-align: middle; overflow: hidden; }
.cpf-cmc .pf-settle-label { display: block; font-size: 8.5px; color: #5f6b7a; font-weight: 700; }
.cpf-cmc .pf-settle-value { display: block; font-size: 12px; font-weight: 700; margin-top: 1px; color: #1f2937; }
.cpf-cmc .pf-settle-net { background: #0f766e !important; border-color: #0f766e !important; }
.cpf-cmc .pf-settle-net .pf-settle-label { color: #d9ece9 !important; }
.cpf-cmc .pf-settle-net .pf-settle-value { color: #ffffff !important; font-size: 13.5px; }
.cpf-cmc .pf-inwords { margin-top: 5px; font-size: 9px; color: #24364a; background: #eef2f7 !important; border: 1px dashed #b9c4d0; padding: 3px 10px; border-radius: 3px; white-space: normal; word-wrap: break-word; word-break: break-word; overflow-wrap: anywhere; }

/* ---------- adjustments ---------- */
.cpf-cmc .pf-section-title { margin: 8px 0 3px; font-size: 10px; font-weight: 700; color: #24364a; border-right: 3px solid #0f766e; padding-right: 6px; }
.cpf-cmc .pf-adjust thead th { background: #eef2f7 !important; color: #24364a; border: 1px solid #dde4ec; padding: 3px 6px; font-size: 8.8px; text-align: right; }
.cpf-cmc .pf-adjust td { border: 1px solid #dde4ec; padding: 2.5px 6px; font-size: 9px; overflow: hidden; }
.cpf-cmc .pf-adjust .c-idx { width: 4%; text-align: center; color: #5f6b7a; }
.cpf-cmc .pf-adjust .c-type { width: 14%; }
.cpf-cmc .pf-adjust .c-desc { width: 64%; }
.cpf-cmc .pf-adjust .c-amount { width: 18%; text-align: left; font-weight: 600; }
.cpf-cmc .pf-pos { color: #0f766e; font-weight: 600; }
.cpf-cmc .pf-neg { color: #b42318; font-weight: 600; }

/* ---------- signatures + footer ---------- */
.card-pf .pf-sign { margin-top: 14px; page-break-inside: avoid; }
.card-pf .pf-sign td { width: 33.33%; padding: 0 12px; text-align: center; border: 0; }
.card-pf .pf-sign-role { font-size: 9.5px; font-weight: 700; color: #24364a; }
.card-pf .pf-sign-line { height: 26px; border-bottom: 1.2px solid #5f6b7a; margin: 4px 8px 3px; }
.card-pf .pf-sign-hint { font-size: 8px; color: #8b97a5; }
.card-pf .pf-footer { margin-top: 10px; padding-top: 4px; border-top: 1px solid #dde4ec; text-align: center; font-size: 8px; color: #8b97a5; }
